    /// only happen in catastrophic conditions, like memory running out. Normally there will be a yes or no to the
    /// request through the callback.
    /// </para>
    /// <para>For the <c>permission</c> parameter, choose a value from here:</para>
    /// <para>https://developer.android.com/reference/android/Manifest.permission</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// <c>cb</c> is a <c>SDL_RequestAndroidPermissionCallback</c>: Callback that presents a response from a
    /// SDL_RequestAndroidPermission call.
    /// </para>
    /// <list type="bullet">
    /// <item>
    /// <description><c>userdata</c>: an app-controlled pointer that is passed to the callback.</description>
    /// </item>
    /// <item>
    /// <description><c>permission</c>: the Android-specific permission name that was requested.</description>
    /// </item>
    /// <item><description><c>granted</c>: true if permission is granted, false if denied.</description></item>
    /// </list>
    /// </remarks>
    /// <param name="permission">the permission to request.</param>
    /// <param name="cb">the callback to trigger when the request has a response.</param>
    /// <param name="userdata">an app-controlled pointer that is passed to the callback.</param>
    /// <returns>
    /// true if the request was submitted, false if there was an error submitting. The result of the request is only
    /// ever reported through the callback, not this return value.
    /// </returns>
    [SupportedOSPlatform("android")]
    public static bool RequestAndroidPermission(ReadOnlySpan<byte> permission, delegate* unmanaged[Cdecl]<void*, byte*, bool, void> cb, void* userdata)
    {
        using var permissionUtf8 = new NulTerminatedUtf8(permission, stackalloc byte[NulTerminatedUtf8.StackLength]);
        fixed (byte* permissionPtr = permissionUtf8)
        {
            return RequestAndroidPermission(permissionPtr, cb, userdata);
        }
    }

